const words=n=>String(n||'').toLowerCase();
export class MediaOrgan {
  constructor(){this.id='media';this.capabilities=['draw','image','video','visualize','animate'];}
  accepts(intent){return /\b(draw|image|picture|visual|video|animate|scene)\b/i.test(intent);}
  spec(intent,address){const t=words(intent);const video=/\b(video|animate|animation|clip)\b/.test(t);const dims=t.match(/(\d{2,4})\s*[x×]\s*(\d{2,4})/);return {kind:video?'video':'image',width:dims?+dims[1]:512,height:dims?+dims[2]:512,duration:video?Math.min(15,+(t.match(/(\d+)\s*seconds?/)?.[1]||5)):0,address,prompt:intent};}
  async execute({intent,address,canvas}){const spec=this.spec(intent,address);if(!canvas)return {ok:true,spec,artifact:{type:'visual-spec',spec}};canvas.width=spec.width;canvas.height=spec.height;const x=canvas.getContext('2d');const seed=(address?.micro?.gate||0)+1;const grad=x.createLinearGradient(0,0,canvas.width,canvas.height);grad.addColorStop(0,'#07070b');grad.addColorStop(1,'#24183b');x.fillStyle=grad;x.fillRect(0,0,canvas.width,canvas.height);const count=64;for(let i=0;i<count;i++){const a=(i/count)*Math.PI*2+seed*.07,r=(Math.min(canvas.width,canvas.height)*.12)+(i/count)*Math.min(canvas.width,canvas.height)*.32;const px=canvas.width/2+Math.cos(a)*r,py=canvas.height/2+Math.sin(a)*r;const hue=(i*11+seed*17)%360;x.beginPath();x.arc(px,py,2+(i%5),0,Math.PI*2);x.fillStyle=`hsl(${hue} 80% 65%)`;x.fill();}x.fillStyle='rgba(255,255,255,.9)';x.font='16px system-ui';x.fillText(String(intent).slice(0,52),18,28);if(spec.kind==='image')return {ok:true,spec,artifact:{type:'image/png',dataUrl:canvas.toDataURL('image/png')}};if(!canvas.captureStream||!globalThis.MediaRecorder)return {ok:true,spec,artifact:{type:'video-plan',note:'MediaRecorder unavailable in this browser'}};const stream=canvas.captureStream(30),chunks=[];let rec;try{rec=new MediaRecorder(stream,{mimeType:'video/webm'})}catch{rec=new MediaRecorder(stream)};return await new Promise(resolve=>{rec.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data)};rec.onstop=()=>resolve({ok:true,spec,artifact:{type:'video/webm',blob:new Blob(chunks,{type:'video/webm'})}});rec.start();const start=performance.now(),dur=spec.duration*1000;const frame=now=>{const p=Math.min(1,(now-start)/dur);x.save();x.globalCompositeOperation='lighter';x.fillStyle='rgba(10,6,20,.09)';x.fillRect(0,0,canvas.width,canvas.height);for(let i=0;i<24;i++){const a=p*Math.PI*4+i*.4,r=30+i*7;x.beginPath();x.arc(canvas.width/2+Math.cos(a)*r,canvas.height/2+Math.sin(a)*r,3,0,Math.PI*2);x.fillStyle=`hsl(${(i*17+p*240)%360} 85% 65%)`;x.fill()}x.restore();if(p<1)requestAnimationFrame(frame);else setTimeout(()=>rec.stop(),150)};requestAnimationFrame(frame)});}
}
export default MediaOrgan;
